<script type="module">
import init, { WasmSession } from './$JS';

// Faithful port of statement_groups::group_statements (Rust).
function bracketDelta(line) {
  let depth = 0, inStr = false, esc = false;
  for (const c of line) {
    if (inStr) { if (esc) esc = false; else if (c === '\\\\') esc = true; else if (c === '"') inStr = false; continue; }
    if (c === '"') inStr = true;
    else if (c === '#') break;
    else if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') depth--;
  }
  return depth;
}
function groupStatements(text) {
  const groups = []; let buf = '', depth = 0;
  for (const line of text.split('\n')) {
    const t = line.trim();
    if (!t) continue;
    if (buf) buf += '\n';
    buf += t;
    if (t.startsWith('#')) continue;
    depth += bracketDelta(t);
    if (depth <= 0) { groups.push(buf); buf = ''; depth = 0; }
  }
  if (buf) groups.push(buf);
  return groups;
}

async function main() {
  await init({ module_or_path: './$WASM' });
  const payloads = await (await fetch('./payload.json')).json();
  const log = [];
  for (const [name, src] of Object.entries(payloads)) {
    const groups = groupStatements(src);
    const s = new WasmSession();
    let last = '', errors = [], svgEntries = 0;
    groups.forEach((g, i) => {
      let r;
      try { r = s.eval(g); } catch (e) { r = 'THREW: ' + e; }
      if (r && r.trim()) {
        last = r;
        if (r.trimStart().startsWith('<svg')) svgEntries++;
        if (r.startsWith('error')) errors.push('g' + i + ': ' + r.slice(0, 90) + '  <<< ' + g.split('\n').pop().slice(0, 60));
      }
    });
    log.push('=== ' + name + '  groups=' + groups.length + ' svgEntries=' + svgEntries + ' errors=' + errors.length);
    log.push('   LAST: ' + String(last).slice(0, 90).replace(/\n/g, ' | '));
    errors.slice(0, 3).forEach(e => log.push('   ERR ' + e));
  }
  document.documentElement.setAttribute('data-harness', log.join(' ~~ '));
  document.title = 'done';
}
main().catch(e => { document.documentElement.setAttribute('data-harness', 'FATAL ' + e); document.title = 'done'; });
</script>
