<!doctype html><meta charset=utf-8><title>harness</title>
<script type="module">
import init, { WasmSession } from './$JS';
function bracketDelta(line) {
  let depth = 0, inStr = false, esc = false;
  for (const c of line) {
    if (inStr) { if (esc) esc = false; else if (c === '\\\\') esc = true; else if (c === '"') inStr = false; continue; }
    if (c === '"') inStr = true; else if (c === '#') break;
    else if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') depth--;
  }
  return depth;
}
function groupStatements(text) {
  const groups = []; let buf = '', depth = 0;
  for (const line of text.split('\n')) {
    const t = line.trim(); if (!t) continue;
    if (buf) buf += '\n';
    buf += t;
    if (t.startsWith('#')) continue;
    depth += bracketDelta(t);
    if (depth <= 0) { groups.push(buf); buf = ''; depth = 0; }
  }
  if (buf) groups.push(buf);
  return groups;
}
async function main() {
  await init({ module_or_path: './$WASM' });
  const payloads = await (await fetch('./payload.json')).json();
  const log = [];
  for (const [name, src] of Object.entries(payloads)) {
    const groups = groupStatements(src);
    const s = new WasmSession();
    log.push('=== ' + name + ' (' + groups.length + ' groups)');
    groups.forEach((g, i) => {
      let r; try { r = s.eval(g); } catch (e) { r = 'THREW ' + e; }
